// Rule R10
// If the claim is reported more than 30 days after the incident, it is flagged as a late report and its status is set to Manual review.
// Source: flow.json, actions.Condition_LateReport
// Formula: div(sub(ticks(ReportedDate), ticks(IncidentDate)), 864000000000) > 30
// Generated by fluxora generate (Rebuild) from the approved rule register. Do not edit by hand.
// The method body was written by the LLM from this rule's register entry; the rest is deterministic.

namespace Fluxora.Generated.Rules;

public static class R10
{
    public const string Status = "Manual review";

    // Rule R10
    public static bool Applies(DateOnly reportedDate, DateOnly incidentDate)
    {
        const long TicksPerDay = 864000000000L;
        var reportedTicks = reportedDate.ToDateTime(TimeOnly.MinValue).Ticks;
        var incidentTicks = incidentDate.ToDateTime(TimeOnly.MinValue).Ticks;
        return (reportedTicks - incidentTicks) / TicksPerDay > 30;
    }
}
